{
  "modules": [
    {
      "name": "callisto-model",
      "path": "crates/callisto-model",
      "responsibility": "Owns provider-neutral domain primitives, strict versioned durable release schemas, deterministic canonical encodings, diagnostic value types, command and registry seams, mutation permits, and crash-safe atomic persistence without workspace discovery or provider orchestration.",
      "depends_on": []
    },
    {
      "name": "callisto-format",
      "path": "crates/callisto-format",
      "responsibility": "Owns changeset and prerelease document grammars plus their format-preserving parsing and rendering.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "callisto-vcs",
      "path": "crates/callisto-vcs",
      "responsibility": "Owns native and command-backed Git access, commit walking, release workspace trust observations, locking, and tag mutation behind model-layer interfaces.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "callisto-manifests",
      "path": "crates/callisto-manifests",
      "responsibility": "Owns CST-preserving Cargo, npm, and Python manifest readers and writers, identity extraction, indentation preservation, and batched persistence.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "callisto-conventional",
      "path": "crates/callisto-conventional",
      "responsibility": "Owns conventional-commit parsing, severity inference, prerelease cursor handling, and commit-window analysis.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "callisto-changelog",
      "path": "crates/callisto-changelog",
      "responsibility": "Owns changelog input modeling, deterministic Markdown rendering, and atomic changelog persistence.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "callisto-graph",
      "path": "crates/callisto-graph",
      "responsibility": "Owns workspace discovery and configuration resolution, dependency and group solving, release-decision and intent derivation, provider-input preparation, authorization, release execution, and cross-ecosystem orchestration.",
      "depends_on": [
        "callisto-model",
        "callisto-format",
        "callisto-vcs",
        "callisto-manifests",
        "callisto-conventional",
        "callisto-changelog"
      ]
    },
    {
      "name": "callisto-cli",
      "path": "crates/callisto-cli",
      "responsibility": "Owns the standalone command surface, argument validation, terminal and JSON presentation, filesystem handoff loading, and wiring from user commands to graph operations.",
      "depends_on": [
        "callisto-model",
        "callisto-format",
        "callisto-vcs",
        "callisto-manifests",
        "callisto-conventional",
        "callisto-changelog",
        "callisto-graph"
      ]
    },
    {
      "name": "callisto-moon",
      "path": "crates/callisto-moon",
      "responsibility": "Owns the Moon/Extism WASI adapter, host-command bridge, plugin configuration surface, and delegation into the graph engine.",
      "depends_on": [
        "callisto-model",
        "callisto-graph"
      ]
    },
    {
      "name": "callisto-fixtures",
      "path": "crates/callisto-fixtures",
      "responsibility": "Owns dev-only byte-compatible corpus samples and reusable test doubles; it is not a runtime dependency or a release unit.",
      "depends_on": [
        "callisto-model"
      ]
    },
    {
      "name": "github-release-orchestration",
      "path": ".github",
      "responsibility": "Owns repository-specific CI policy, release-pull-request orchestration, runner job isolation, artifact transport, credential scoping, and invocation of the provider-neutral CLI; it must not become an independent release planner or authority model.",
      "depends_on": [
        "callisto-cli"
      ]
    }
  ],
  "canonical_abstractions": [
    {
      "concept": "human-facing package identity",
      "type_or_interface": "PackageId",
      "location": "crates/callisto-model/src/identity.rs",
      "rationale": "Workspace lookup may accept its documented bare or ecosystem-qualified forms; durable release operations must promote it to ReleasePackageId."
    },
    {
      "concept": "durable release package identity",
      "type_or_interface": "ReleasePackageId",
      "location": "crates/callisto-model/src/release.rs",
      "rationale": "It is always ecosystem-qualified and has one canonical serialization, preventing cross-ecosystem aliasing in durable authority."
    },
    {
      "concept": "ecosystem-aware version",
      "type_or_interface": "Version",
      "location": "crates/callisto-model/src/version.rs",
      "rationale": "It retains the version grammar and canonical rendering used by decisions, manifests, tags, and provider identities."
    },
    {
      "concept": "permission to mutate",
      "type_or_interface": "ApplyPermit",
      "location": "crates/callisto-model/src/permit.rs",
      "rationale": "Mutating paths require an unforgeable value that read-only and dry-run paths do not receive."
    },
    {
      "concept": "command execution seam",
      "type_or_interface": "CommandRunner",
      "location": "crates/callisto-model/src/exec.rs",
      "rationale": "External process invocation and timeout behavior are injected for deterministic boundary testing."
    },
    {
      "concept": "crash-safe file replacement",
      "type_or_interface": "atomic_write",
      "location": "crates/callisto-model/src/atomic.rs",
      "rationale": "All authoritative manifest, configuration, state, and receipt persistence must use one same-directory flush-and-rename implementation."
    },
    {
      "concept": "manifest editing",
      "type_or_interface": "Manifest",
      "location": "crates/callisto-manifests/src/common.rs",
      "rationale": "It centralizes ecosystem-specific CST access, mutation permits, batching, and persistence rather than allowing orchestration code to hand-edit source files."
    },
    {
      "concept": "Git data and mutation access",
      "type_or_interface": "GitDataSource",
      "location": "crates/callisto-vcs/src/lib.rs",
      "rationale": "Native and shell backends implement one semantic contract for commit, tag, and history operations."
    },
    {
      "concept": "approved release roster and target versions",
      "type_or_interface": "ReleaseDecisionV1",
      "location": "crates/callisto-model/src/release.rs",
      "rationale": "It is the deterministic, credential-free output of graph policy resolution and prevents executors from widening the approved roster."
    },
    {
      "concept": "immutable release operation plan",
      "type_or_interface": "ReleaseIntentV1",
      "location": "crates/callisto-model/src/release.rs",
      "rationale": "It binds the decision, source identity, semantic inputs, exact operation DAG, and required artifact slots under a canonical digest."
    },
    {
      "concept": "validated release capability",
      "type_or_interface": "ValidatedReleaseIntent",
      "location": "crates/callisto-graph/src/commands/release.rs",
      "rationale": "It privately retains re-observed trust evidence, the workspace lock, and exact prepared provider inputs required before effects."
    },
    {
      "concept": "operational release attempt history",
      "type_or_interface": "ReleaseExecutionStateV1 and ReleaseStateStore",
      "location": "crates/callisto-model/src/release.rs and crates/callisto-graph/src/commands/release_store.rs",
      "rationale": "The state records attempts and safe terminal evidence bound to an intent; it is operational evidence, not the authority for what should exist externally."
    },
    {
      "concept": "release completion evidence",
      "type_or_interface": "ReleaseReceiptV1",
      "location": "crates/callisto-model/src/release.rs",
      "rationale": "A successful receipt is the durable local representation of complete terminal outcomes, but must only be emitted after final external convergence checks."
    },
    {
      "concept": "intent-bound artifact inventory",
      "type_or_interface": "ArtifactManifestV1",
      "location": "crates/callisto-model/src/release.rs",
      "rationale": "It binds each required asset slot to exact bytes, length, source commit, repository, and attestation identity."
    },
    {
      "concept": "release pull request decision",
      "type_or_interface": "ReleasePrDecisionV2 and ReleasePrCommitPlanV1",
      "location": "crates/callisto-model/src/release_pr.rs",
      "rationale": "The action and CLI share versioned strict models for the managed release-PR action and its exact commit mutation plan."
    }
  ],
  "invariants": [
    {
      "name": "safe-rust-only",
      "rule": "Every workspace crate forbids unsafe Rust.",
      "rationale": "Callisto operates on source trees and publication credentials, so unchecked memory behavior is outside the accepted trust model.",
      "enforced_by": "[workspace.lints.rust] unsafe_code = forbid plus just lint"
    },
    {
      "name": "layer-and-license-direction",
      "rule": "callisto-model, callisto-format, and callisto-vcs never depend on AGPL orchestration crates; higher layers may depend only downward through the declared module graph.",
      "rationale": "Provider-neutral primitives and permissively licensed foundations must remain reusable without importing orchestration or stronger-license dependencies.",
      "enforced_by": "Cargo workspace dependency graph review; crate Cargo.toml manifests"
    },
    {
      "name": "format-preserving-manifest-edits",
      "rule": "Manifest edits use the canonical manifest abstractions and preserve comments, key order, and indentation; orchestration code does not use regex or line replacement for structured manifests.",
      "rationale": "Versioning must not create unrelated source churn or corrupt user formatting.",
      "enforced_by": "callisto-manifests tests and crates/callisto-graph/tests/architecture.rs"
    },
    {
      "name": "atomic-authoritative-writes",
      "rule": "Manifest, configuration, release state, and receipt writes use callisto_model::atomic::atomic_write.",
      "rationale": "A process or runner interruption must leave either the old complete file or the new complete file.",
      "enforced_by": "atomic_write call sites plus persist-call-count and release-store tests"
    },
    {
      "name": "mutation-requires-permit",
      "rule": "Every filesystem, Git, registry, or forge mutation requires ApplyPermit and is unreachable from structurally read-only commands.",
      "rationale": "Dry-run and inspection safety is enforced by type reachability instead of convention.",
      "enforced_by": "ApplyPermit signatures, dry-run invariant tests, and CLI lifecycle tests"
    },
    {
      "name": "durable-release-authority-is-typed-and-secret-free",
      "rule": "Release decisions and intents contain only strict versioned typed identities and canonical digests; they contain no credentials, raw endpoints, provider stderr, mutable environment-derived authority, or arbitrary command lines.",
      "rationale": "The reviewed release authority must be deterministic, inspectable, portable across runners, and safe to persist.",
      "enforced_by": "ReleaseDecisionV1 and ReleaseIntentV1 constructors/deserializers plus schema and secret-safety tests"
    },
    {
      "name": "executor-cannot-replan",
      "rule": "Provider dispatch selects an exact prepared operation from a validated immutable intent and cannot discover extra packages, versions, tags, or endpoints from mutable configuration.",
      "rationale": "Approval applies to the reviewed plan, not whatever a later runner happens to discover.",
      "enforced_by": "ValidatedReleaseIntent privacy, release capability tests, and stale-input re-observation"
    },
    {
      "name": "release-state-is-not-release-authority",
      "rule": "Execution state may record attempts and observations but cannot by absence, loss, or an Attempting marker prove success or change the immutable intended operation set.",
      "rationale": "Runner-local state can be lost exactly when a remote effect has already succeeded.",
      "enforced_by": "ReleaseExecutionStateV1 intent binding and reconciliation tests; external observation enforcement remains a known coverage gap at this revision"
    },
    {
      "name": "sibling-gap-discipline",
      "rule": "A defect fix searches structurally identical implementations and either unifies every existing caller behind one canonical implementation or records each deliberate deferral.",
      "rationale": "Parallel shell, CLI, ecosystem, and provider implementations otherwise recreate the same defect under a different spelling.",
      "enforced_by": "AGENTS.md review rule; add architecture tests when a new shared boundary replaces duplication"
    },
    {
      "name": "fixtures-are-not-a-release-unit",
      "rule": "callisto-fixtures may support development and inherit workspace metadata but never appears in a release decision, changeset requirement, publication operation, product tag, or completion blocker.",
      "rationale": "It is test support, not a consumer deliverable.",
      "enforced_by": "Not yet enforced in origin/main; required by REQ-DRAFT-RELEASE-RECOVERY"
    }
  ],
  "last_built_from": "0ffe567f9c404cee233d44a6e4ae69a7868590a2",
  "reasoning": "This model records live crate dependencies and current canonical types. It deliberately does not certify a canonical product-release identity or a complete external observer because those concepts are missing from origin/main and must be introduced by the recovery specification. The .github directory is modeled as an orchestration adapter, not as a second planner."
}

