                stderr: String::new(),
            }))
        }
    }

    fn intent_with_slot(slot: ArtifactSlotId) -> ReleaseIntentV1 {
        use callisto_model::{
            ExecutionTrustProfileV1, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason,
            ReleaseInputSnapshotV1, ReleaseOperation, SourceIdentity,
        };
        let source = callisto_model::CommitSha::parse("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa").unwrap();
        let snapshot = ReleaseInputSnapshotV1::new(SourceIdentity::GitCommit { sha: source.clone() }, vec![]).unwrap();
        let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
            package: slot.package.clone(),
            target_version: slot.version.clone(),
            reasons: vec![ReleaseInclusionReason::ExplicitSelection],
        }])
        .unwrap();
        let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![]).unwrap();
        ReleaseIntentV1::new(
            decision,
            snapshot,
            ExecutionTrustProfileV1::GitCommit,
            vec![operation],
            vec![slot],
        )
        .unwrap()
    }

    fn manifest_for(intent: &ReleaseIntentV1, digest: ArtifactDigest, length: u64) -> ArtifactManifestV1 {
        let slot = intent.artifact_slots[0].clone();
        let attestation = GitHubArtifactAttestationV1 {
            repository: slot.attestation_policy.repository.clone(),
            workflow_path: slot.attestation_policy.workflow_path.clone(),
            workflow_commit: slot.attestation_policy.workflow_commit.clone(),
            subject_digest: digest.clone(),
            source_commit: match &intent.snapshot.source {
                callisto_model::SourceIdentity::GitCommit { sha } => sha.clone(),
                callisto_model::SourceIdentity::HermeticContent { .. } => panic!("test intent has a Git source"),
            },
        };
        ArtifactManifestV1::new(
            intent,
            vec![ArtifactManifestEntryV1 {
                slot,
                digest,
                byte_length: length,
                attestation,
            }],
        )
        .unwrap()
    }

    fn slot(asset_name: &str) -> ArtifactSlotId {
        let package = ReleasePackageId::new(Ecosystem::Npm, "package").unwrap();
        ArtifactSlotId::new(
            package,
            Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            "linux-x64",
            asset_name,
            GitHubRepository::parse("owner/repository").unwrap(),
            ".github/workflows/release.yml",
            callisto_model::CommitSha::parse("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb").unwrap(),
        )
        .unwrap()
    }

    #[test]
    fn verifies_exact_bytes_and_pinned_github_policy() {
        let directory = tempdir().unwrap();
        let bytes = b"trusted artifact";
        fs::write(directory.path().join("artifact.tar.gz"), bytes).unwrap();
        let intent = intent_with_slot(slot("artifact.tar.gz"));
        let manifest = manifest_for(&intent, ArtifactDigest::from_bytes(bytes), bytes.len() as u64);
        let runner = RecordingRunner::default();

        let verified = verify_artifact_manifest(&intent, &manifest, directory.path(), &runner).unwrap();
        assert_eq!(verified.manifest(), &manifest);
        let calls = runner.calls.lock().unwrap();
        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].0, "gh");
        assert!(calls[0].1.windows(2).any(|args| args == ["--repo", "owner/repository"]));
        assert!(calls[0]
            .1
            .windows(2)
            .any(|args| args == ["--signer-workflow", "owner/repository/.github/workflows/release.yml"]));
        assert!(calls[0]
            .1
            .windows(2)
            .any(|args| args == ["--signer-digest", "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"]));
        assert!(calls[0]
            .1
            .windows(2)
            .any(|args| args == ["--source-digest", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"]));
        assert!(calls[0].1.contains(&"--deny-self-hosted-runners".to_owned()));
    }

    #[test]
    fn rejects_changed_artifact_without_attestation_lookup() {
        let directory = tempdir().unwrap();
        fs::write(directory.path().join("artifact.tar.gz"), b"changed").unwrap();
        let intent = intent_with_slot(slot("artifact.tar.gz"));
        let manifest = manifest_for(&intent, ArtifactDigest::from_bytes(b"original"), 8);
        let runner = RecordingRunner::default();

        assert!(matches!(
            verify_artifact_manifest(&intent, &manifest, directory.path(), &runner),
            Err(GraphError::ArtifactBytesMismatch { .. })
        ));
        assert!(runner.calls.lock().unwrap().is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn rejects_symlink_artifacts_without_attestation_lookup() {
        use std::os::unix::fs::symlink;
        let directory = tempdir().unwrap();
        let outside = tempdir().unwrap();
        fs::write(outside.path().join("artifact.tar.gz"), b"outside").unwrap();
        symlink(
            outside.path().join("artifact.tar.gz"),
            directory.path().join("artifact.tar.gz"),
        )
        .unwrap();
        let intent = intent_with_slot(slot("artifact.tar.gz"));
        let manifest = manifest_for(&intent, ArtifactDigest::from_bytes(b"outside"), 7);
        let runner = RecordingRunner::default();

        assert!(matches!(
            verify_artifact_manifest(&intent, &manifest, directory.path(), &runner),
            Err(GraphError::UnsafeArtifactPath { .. })
        ));
        assert!(runner.calls.lock().unwrap().is_empty());
    }
}
    Ok(ReleaseIntentV1::new(
        decision.clone(),
        snapshot,
        trust_profile,
        operations,
        vec![],
    )?)
}

fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<(ReleaseIntentV1, PreparedDerivation), GraphError> {
    let (snapshot, operations, prepared, git_remote) = derive_release_inputs(workspace, decision, source)?;
    let intent = ReleaseIntentV1::new(decision.clone(), snapshot, trust_profile, operations, vec![])?;
    Ok((
        intent,
        PreparedDerivation {
            operations: prepared,
            git_remote,
        },
    ))
}

fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
) -> Result<DerivedReleaseInputs, GraphError> {
    let mut package_inputs = Vec::new();

    let mut selected = BTreeMap::new();
    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
    for package in workspace.graph.packages() {
        // One canonical manifest per ecosystem is the expected shape, but
        // dedup defensively -- `release_package_ids` maps every canonical
        // manifest, and two manifests sharing an ecosystem would otherwise
        // select/push the same identity twice.
        for id in super::release_decision::release_package_ids(package)?
            .into_iter()
            .collect::<BTreeSet<_>>()
        {
            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
                selected.insert(id.clone(), (package, entry.target_version.clone()));
                package_ids.entry(package.id.clone()).or_default().push(id);
            }
        }
    }
    for entry in &decision.entries {
        let id = &entry.package;
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    let requires_git_remote = selected.values().any(|(package, _)| {
        package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None))
    });
    let git_remote = requires_git_remote
        .then(|| prepared_git_remote(&workspace.root, workspace.runner))
        .transpose()?;

    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();

    // First construct leaves so dependency prerequisites can refer only to
    // exact selected release identities, never PackageId's wildcard matcher.
    for (id, (package, version)) in &selected {
        let produces_tag = package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None));
        let fingerprint = package_fingerprint(
            workspace,
            id,
            package,
            version,
            produces_tag.then_some(git_remote.as_ref()).flatten(),
        )?;
        package_inputs.push(ReleasePackageInputV1 {
            package: id.clone(),
            fingerprint,
        });

        let mut publishes = Vec::new();
        for target in &package.publish_to {
            if target.ecosystem() == Some(id.ecosystem()) {
                let registry_key = target.registry_key().expect("registry target has registry key");
                let binding = prepared_registry_binding(workspace, target)?;
                let operation = ReleaseOperation::registry_publish(
                    id.clone(),
                    version.clone(),
                    RegistryBindingId::new(registry_key.as_str(), binding.identity.clone())?,
                    Vec::new(),
                )?;
                // A durable registry operation must have one exact endpoint
                // binding. The model-level operation identity currently has
                // only a registry key, so reject a second target that would
                // collapse to the same operation until the typed binding
                // identity is added there.
                if prepared.contains_key(operation.id()) {
                    return Err(GraphError::ReleaseSelectionInvalid {
                        package: id.clone(),
                        reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
                    });
                }
                prepared.insert(
                    operation.id().clone(),
                    PreparedOperation::RegistryPublish {
                        package_dir: package_dir(package)?,
                        package_name: id.name().to_string(),
                        version: version.clone(),
                        registry: binding,
                        npm_access: match target {
                            PublishTarget::Npm { access, .. } => *access,
                            _ => None,
                        },
                        npm_tag: matches!(target, PublishTarget::Npm { .. })
                            .then(|| version.is_prerelease().then_some("next".to_string()))
                            .flatten(),
                    },
                );
                publishes.push(operation.id().clone());
                operations.insert(operation.id().clone(), operation);
            }
        }
        publishes.sort();
        publishes_by_package.insert(id.clone(), publishes);
    }

    // Replace each publish leaf with prerequisites from selected dependency
    // packages. This preserves the existing publish semantics: runtime,
    // build, optional, and dev dependencies must exist before publish.
    for (id, (package, _)) in &selected {
        let mut prerequisites = BTreeSet::new();
        for edge in workspace.graph.dependencies_of(&package.id) {
            if !matches!(
                edge.kind,
                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
            ) {
                continue;
            }
            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
                prerequisites.extend(
                    publishes_by_package
                        .get(dependency_release_id)
                        .into_iter()
                        .flatten()
                        .cloned(),
                );
            }
        }
        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
            let operation = operations.get(publish_id).expect("publish operation was constructed");
            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())?;
            operations.insert(publish_id.clone(), replacement);
        }
    }

    for (id, (package, version)) in &selected {
        if !package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None))
        {
            continue;
        }
        let tag = ReleaseOperation::tag(
            id.clone(),
            version.clone(),
            publishes_by_package.get(id).cloned().unwrap_or_default(),
        )?;
        let tag_name = package
            .tag_template
            .clone()
            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
            .render(version);
        let target = match &source {
            SourceIdentity::GitCommit { sha } => sha.clone(),
            SourceIdentity::HermeticContent { .. } => {
                return Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::SourceIdentity,
                })
            }
        };
        prepared.insert(
            tag.id().clone(),
            PreparedOperation::Tag {
                annotation: format!("Release {tag_name}"),
                name: tag_name,
                target,
            },
        );
        tag_by_package.insert(id.clone(), tag.id().clone());
        operations.insert(tag.id().clone(), tag);
    }
    for (id, (package, version)) in &selected {
        if package
            .publish_to
            .iter()
            .any(|target| matches!(target, PublishTarget::GitHubRelease))
        {
            let tag = tag_by_package.get(id).expect("release point has tag").clone();
            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
                Some(PreparedOperation::Tag { name, .. }) => name.clone(),
                _ => {
                    return Err(GraphError::ReleaseInvariant {
                        detail: format!(
                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
                            operation.id()
                        ),
                    })
                }
            };
            prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
            operations.insert(operation.id().clone(), operation);
        }
    }

    Ok((
        ReleaseInputSnapshotV1::new(source, package_inputs)?,
        canonical_operation_order(operations)?,
        prepared,
        git_remote,
    ))
}

fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    id: &ReleasePackageId,
    package: &callisto_model::Package,
    version: &Version,
    git_remote: Option<&PreparedGitRemote>,
) -> Result<SemanticInputDigest, GraphError> {
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str("package.id", &id.to_string());
    transcript.push_str("package.version", version.render());
    for manifest in &package.manifests {
        let path = workspace.root.join(&manifest.path);
        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
            path: manifest.path.clone(),
            message: error.to_string(),
        })?;
        transcript.push_str("manifest.path", &manifest.path.display().to_string());
        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
    }
    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
    transcript.push_str(
        "package.tag",
        &package
            .tag_template
            .as_ref()
            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
    );
    for target in &package.publish_to {
        transcript.push_str("package.target", target_fingerprint(workspace, target)?.as_str());
    }
    if let Some(remote) = git_remote {
        transcript.push_str("package.gitRemote", remote.identity.as_str());
    }
    Ok(SemanticInputDigest::from_transcript(&transcript))
                program: "gh".to_string(),
                args: create_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: created.exit_code,
                    stderr: created.stderr,
                },
            });
        }
        if self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeReleaseNotObservedAfterCreate,
            })
        }
    }

    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
        let reference = format!("refs/tags/{name}^{{commit}}");
        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Ok(None);
        }
        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
            program: "git".to_string(),
            args: rev_parse_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let for_each_ref_target = format!("refs/tags/{name}");
        let for_each_ref_args = [
            "for-each-ref",
            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
            for_each_ref_target.as_str(),
        ];
        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
        if details.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: details.exit_code,
                    stderr: details.stderr,
                },
            });
        }
        let line = details.stdout.trim_end_matches(['\r', '\n']);
        let mut fields = line.split('\0');
        let object_type = fields.next();
        let annotation = fields.next();
        let body = fields.next();
        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::MalformedOutput {
                    detail: format!("unexpected for-each-ref output: {line:?}"),
                },
            });
        }
        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
        })?;
        Ok(Some(ObservedTag {
            target,
            annotation: annotation.to_string(),
        }))
    }

    fn observed_forge_release_target(
        &self,
        tag: &TagName,
        repository: &str,
    ) -> Result<ForgeReleaseObservation, GraphError> {
        let endpoint = format!("repos/{repository}/releases/tags/{tag}");
        let api_args = [
            "api",
            "--include",
            "--method",
            "GET",
            endpoint.as_str(),
            "--repo",
            repository,
        ];
        let observed = self.runner.run("gh", &api_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: api_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: observed.exit_code,
                    stderr: observed.stderr,
                },
            });
        }
        let (status, body) = parse_github_api_response("gh", &api_args, &observed.stdout)?;
        if status == 404 {
            return Ok(ForgeReleaseObservation::Missing);
        }
        if status != 200 {
            return Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeApiStatus,
            });
        }
        let value: serde_json::Value = serde_json::from_str(body).map_err(|error| GraphError::ReleaseCommand {
            program: "gh".to_string(),
            args: api_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let expected = match &self.prepared.source {
            SourceIdentity::GitCommit { sha } => sha.as_str(),
            SourceIdentity::HermeticContent { .. } => {
                return Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::SourceIdentity,
                })
            }
        };
        Ok(
            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
            {
                ForgeReleaseObservation::Exact
            } else {
                ForgeReleaseObservation::Conflict
            },
        )
    }

    fn checked_git_remote(&self) -> Result<&PreparedGitRemote, GraphError> {
        let expected = self
            .prepared
            .git_remote
            .as_ref()
            .ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::GitRemotePrepared,
            })?;
        if prepared_git_remote(&self.prepared.root, self.runner)? != *expected {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(expected)
    }
}

