   153	/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
   154	/// (2) a well-formed workspace table with members/exclude arrays of
   155	/// strings. Every other shape (workspace table absent, TOML unparseable,
   156	/// members/exclude present but not an array-of-strings, members key
   157	/// absent) falls back to an absent-filter (admit-all) result -- see the
   158	/// `cargo_membership_tests`/`python_membership_tests` modules for the
   159	/// exact fallback matrix this is pinned against.
   160	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
   161	    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
   162	        Ok(c) => c,
   163	        Err(_) => return Membership::absent(),
   164	    };
   165	    let doc = match content.parse::<toml_edit::DocumentMut>() {
   166	        Ok(d) => d,
   167	        Err(_) => return Membership::absent(),
   168	    };
   169	
   170	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
   171	    for key in &spec.table_path[1..] {
   172	        cursor = cursor.and_then(|c| c.get(*key));
   173	    }
   174	
   175	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
   176	    let Some(workspace) = cursor else {
   177	        return Membership {
   178	            members: None,
   179	            exclude: NegatableGlobSet::empty(),
   180	            hybrid_root,
   181	        };
   182	    };
   183	    let members = workspace
   184	        .get("members")
   185	        .and_then(parse_toml_string_array)
   186	        .map(|v| build_globset(&v));
   187	    let exclude = workspace
   188	        .get("exclude")
   189	        .and_then(parse_toml_string_array)
   190	        .map(|v| build_globset(&v))
   191	        .unwrap_or_else(NegatableGlobSet::empty);
   192	    Membership {
   193	        members,
   194	        exclude,
   195	        hybrid_root,
   196	    }
   197	}
