   341	/// True when the root package.json exists, parses as JSON, and declares a
   342	/// "name" field. Independent of which arm (package.json "workspaces" or a
   343	/// sibling pnpm-workspace.yaml) governs the rest of npm membership -- see
   344	/// AC-16/AC-16b/AC-17/AC-10d.
   345	fn package_json_declares_name(root: &Path) -> bool {
   346	    let Ok(content) = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())) else {
   347	        return false;
   348	    };
   349	    let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) else {
