   369	/// YAML-parse-Err, zero-documents, packages-key-missing-or-wrong-shape, and
   370	/// a non-string sequence element all safely fall back to `None` (which
   371	/// causes `read_npm_membership` to fall through to
   372	/// `read_package_json_workspaces` or admit-all).
   373	fn read_pnpm_packages(root: &Path) -> Option<Vec<String>> {
   374	    let content = std::fs::read_to_string(root.join("pnpm-workspace.yaml")).ok()?;
   375	    let docs = yaml_rust2::YamlLoader::load_from_str(&content).ok()?;
   376	    let doc = docs.first()?;
   377	    let packages = doc["packages"].as_vec()?;
   378	    let mut out = Vec::with_capacity(packages.len());
   379	    for item in packages {
   380	        out.push(item.as_str()?.to_string());
   381	    }
   382	    Some(out)
   383	}
   384	
   385	/// File-absent, field-absent, non-array "workspaces", and non-string array
   386	/// entries all safely fall back to `None` (a plain `?`-chain), which causes
   387	/// `read_npm_membership` to admit-all.
   388	fn read_package_json_workspaces(root: &Path) -> Option<Vec<String>> {
   389	    let content = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())).ok()?;
   390	    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
   391	    let field = val.get("workspaces")?;
   392	    let arr = field.as_array()?;
   393	    let mut out = Vec::with_capacity(arr.len());
   394	    for v in arr {
   395	        out.push(v.as_str()?.to_string());
   396	    }
   397	    Some(out)
   398	}
